package ai.decisionos.aside;
import android.os.Bundle;import org.json.JSONObject;
final class SchoolAccountKeyChecks {
 static void run(GoalInstrumentation i,Bundle args){Bundle out=new Bundle();String a="nubi-key-fixture-a@example.invalid",b="nubi-key-fixture-b@example.invalid";try{
 android.content.Context c=i.getTargetContext();
 if("read".equals(args.getString("keyPhase"))){i.check("fixture-a".equals(SchoolAccountKeys.load(c,a,"portal").getString("marker")),"account A key survives new instrumentation process");i.check("fixture-b".equals(SchoolAccountKeys.load(c,b,"portal").getString("marker")),"account B key survives new instrumentation process");SchoolAccountKeys.clear(c,a);SchoolAccountKeys.clear(c,b);i.check(SchoolAccountKeys.load(c,a,"portal")==null,"account removal");}
 else{SchoolAccountKeys.clear(c,a);SchoolAccountKeys.clear(c,b);SchoolAccountKeys.save(c,a,"portal",new JSONObject().put("marker","fixture-a"));SchoolAccountKeys.save(c,b,"portal",new JSONObject().put("marker","fixture-b"));i.check("fixture-a".equals(SchoolAccountKeys.load(c,a,"portal").getString("marker")),"account A isolated");i.check("fixture-b".equals(SchoolAccountKeys.load(c,b,"portal").getString("marker")),"account B isolated");i.check(SchoolAccountKeys.load(c,a,"mail")==null,"service isolated");android.content.SharedPreferences p=c.getSharedPreferences("school_account_keys_v1",0);for(java.util.Map.Entry<String,?> row:p.getAll().entrySet())if(row.getKey().equals(find(c,a))||row.getKey().equals(find(c,b))){i.check(!row.getValue().toString().contains("fixture-"),"plaintext marker absent");String mail=row.getKey().replace(".portal",".mail");p.edit().putString(mail,row.getValue().toString()).commit();try{SchoolAccountKeys.load(c,row.getKey().equals(find(c,a))?a:b,"mail");throw new AssertionError("cross-service ciphertext accepted");}catch(javax.crypto.AEADBadTagException expected){i.check(true,"GCM service binding rejects copied ciphertext");}finally{p.edit().remove(mail).commit();}}}
 out.putString("stream","PASS "+i.checks+" account key vault checks · "+args.getString("keyPhase","write")+" · synthetic grants only\n");
 }catch(Throwable t){out.putString("stream","FAIL "+t+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
 static String find(android.content.Context c,String subject)throws Exception{byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(subject.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s+".portal";}
}
